-width:210px;padding:7px 9px;border:1px solid #ccd6e0;border-radius:8px;background:#fff;color:#26394b;font-size:14px}.sort-direction{font-size:14px!important;padding:8px 10px!important}#friends.only-name-id .friend-columns,#friends.only-name-id .friend-row{grid-template-columns:minmax(0,1fr) max-content}#friends.only-name-id .contact-list .contact-row{width:100%;min-width:0}#friends.only-name-id .contact-list .contact-row .friend-row-account{width:100%;min-width:0}#friends.only-name-id .contact-list .contact-row .friend-row-account>div.name{display:block;flex:0 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}#friends.only-name-id .contact-list .contact-row .friend-row-vk-id{white-space:nowrap}@media(max-width:800px){#friends .contact-list .contact-row{grid-template-columns:38px minmax(130px,1fr) 95px 110px}#friends .friend-row-comment,#friends .friend-row-days{grid-column:2/-1}.contact-list .contact-row{grid-template-columns:minmax(0,1fr) 95px 120px minmax(0,1.2fr)}}@media(max-width:600px){#friends .contact-list .contact-row{grid-template-columns:34px minmax(0,1fr) 90px}#friends .friend-row-favorite,#friends .friend-row-comment,#friends .friend-row-days{grid-column:2/-1}.contact-list .contact-row{grid-template-columns:minmax(0,1fr) 85px 110px minmax(0,1fr)}}</style>@livewireStyles</head><body><main class="wrap" data-vk-user-id="{{ auth()->user()->vk_id }}">
