@livewireScripts
<script>
let removalTimer=null;
const showRemovalStatus=(message,isError=false,results=[])=>{
    const status=document.getElementById('removal-status');
    if(!status)return;
    status.hidden=false;
    status.classList.toggle('error',isError);
    status.replaceChildren();
    const heading=document.createElement('div');heading.textContent=message;status.append(heading);
    if(results.length){const list=document.createElement('ul');list.style.margin='8px 0 0';list.style.paddingLeft='22px';results.forEach(result=>{const row=document.createElement('li');row.textContent=`VK ID ${result.id}: ${result.label}`;list.append(row)});status.append(list)}
};
document.addEventListener('click',(event)=>{
    const button=event.target.closest('#start-friend-removal');
    if(!button)return;
    const ids=[...document.querySelectorAll('#friends-list input[name="friends[]"]:checked')].map(input=>input.value);
    if(!ids.length){showRemovalStatus('Сначала отметьте друзей на этой странице.',true);return}
    showRemovalStatus('Проверяю выбор и передаю его расширению Firefox…');
    clearTimeout(removalTimer);
    removalTimer=setTimeout(()=>{const currentButton=document.getElementById('start-friend-removal');if(currentButton)currentButton.disabled=false;showRemovalStatus('Нет ответа от расширения Firefox. Проверьте, что оно загружено в about:debugging, и обновите страницу.',true)},30000);
});
window.addEventListener('message',(event)=>{
    if(event.source!==window||event.origin!==location.origin||event.data?.type!=='VKFM_STATUS')return;
    const {phase,message,results=[]}=event.data;
    const done=['complete','stopped','error','cancelled'].includes(phase);
    clearTimeout(removalTimer);
    const button=document.getElementById('start-friend-removal');
    if(phase==='progress'&&button)button.disabled=true;
    else if(done&&button)button.disabled=false;
    else removalTimer=setTimeout(()=>{const currentButton=document.getElementById('start-friend-removal');if(currentButton)currentButton.disabled=false;showRemovalStatus('Нет обновлений от расширения. Проверьте открывшуюся вкладку VK и при необходимости начните снова.',true,results)},30000);
    showRemovalStatus(message||'Статус обработки обновлён.',phase==='error'||phase==='stopped',results);
});
const updatePaginationDock=()=>{
    document.querySelectorAll('.pagination.docked').forEach(nav=>{nav.classList.remove('docked');nav.style.left='';nav.style.width=''});
    const activeSection=[...document.querySelectorAll('.tab-content')].find(section=>!section.hidden);
    const pagination=activeSection?.querySelector('.pagination');
    if(!pagination)return;
    const pageBottom=window.scrollY+window.innerHeight>=document.documentElement.scrollHeight-2;
    if(pageBottom)return;
    const panel=pagination.closest('.panel');
    const bounds=panel?.getBoundingClientRect();
    if(!bounds)return;
    pagination.classList.add('docked');
    pagination.style.left=`${bounds.left}px`;
    pagination.style.width=`${bounds.width}px`;
};
window.addEventListener('scroll',updatePaginationDock,{passive:true});
window.addEventListener('resize',updatePaginationDock);
const managerRoot=document.getElementById('vk-list-manager');
if(managerRoot)new MutationObserver(()=>requestAnimationFrame(updatePaginationDock)).observe(managerRoot,{subtree:true,childList:true,attributes:true,attributeFilter:['hidden']});
requestAnimationFrame(updatePaginationDock);
</script></body></html>
